(2515637, 346839, 58988, '<td valign="top">Good theme!</td>', 'Good theme!', '2006-06-14 08:21:47.000000', NULL, 1),
(2515638, 347589, 21816, '<td valign="top">Wow! Very white teeth!</td>', 'Wow! Very white teeth!', '2006-06-14 08:22:05.000000', NULL, 1),
(2515654, 346961, 50715, '<td valign="top">I like your thinking on this, but the car doesn''t really stand out; I certainly don''t get a strong sense of indulgence.<br/> <br/>The whole photo seems a bit dark to me; I can''t see any tonal differentiation between much of the front car and the shadows underneath; the right side of the car (middle of the picture) blends into the background too much.<br/> <br/>I guess you were trying to stop the reflections on the windscreen from blowing out. Perhaps another location, where some sort of roof or overhang blocked those shadows would have been better?</td>', 'I like your thinking on this, but the car doesn''t really stand out; I certainly don''t get a strong sense of indulgence. The whole photo seems a bit dark to me; I can''t see any tonal differentiation between much of the front car and the shadows underneath; the right side of the car (middle of the picture) blends into the background too much. I guess you were trying to stop the reflections on the windscreen from blowing out. Perhaps another location, where some sort of roof or overhang blocked those shadows would have been better?', '2006-06-14 08:29:25.000000', NULL, 1),
(2515656, 347049, 50715, '<td valign="top">Nice image, but the white of the icecream is a little overbearing - maybe a bit more strawberry syrup would have helped.</td>', 'Nice image, but the white of the icecream is a little overbearing - maybe a bit more strawberry syrup would have helped.', '2006-06-14 08:30:44.000000', NULL, 1),
(2515658, 347600, 50715, '<td valign="top">This image doesn''t scream "indulgence" at me (but I can see where you''re coming from, I would *not* say DNMC). None of that negates the fact that it''s a good image. Shallow depth of field is good. I don''t normally like overly done borders but yours complements the image well. The orange thing in the background in the top left corner does clash though.</td>', 'This image doesn''t scream "indulgence" at me (but I can see where you''re coming from, I would *not* say DNMC). None of that negates the fact that it''s a good image. Shallow depth of field is good. I don''t normally like overly done borders but yours complements the image well. The orange thing in the background in the top left corner does clash though.', '2006-06-14 08:34:51.000000', NULL, 1),
(2515664, 347527, 50715, '<td valign="top">I''m assuming you''re refering to the bra, not the breasts? :) Well composed, good tonal relationships - monochrome works well here. I like your choice of depth-of-field, and the background is nice and clean. Well done.</td>', 'I''m assuming you''re refering to the bra, not the breasts? :) Well composed, good tonal relationships - monochrome works well here. I like your choice of depth-of-field, and the background is nice and clean. Well done.', '2006-06-14 08:38:04.000000', NULL, 1),
(2515666, 346770, 50715, '<td valign="top">Nice choice of subject, and the sharpness and colour are good, but I think the image would be stronger if there was a bit of a sense of action.  Instead of the three occupants staring straight to camera (with not particularly excited looks on their faces), it would be good to see them *enjoying* the indulgence - interacting with each other, putting on the life jackets, or just starting/coming to a stop (i.e. with some bow waves or wake to show movement) would all have dramatically improved the image.</td>', 'Nice choice of subject, and the sharpness and colour are good, but I think the image would be stronger if there was a bit of a sense of action.  Instead of the three occupants staring straight to camera (with not particularly excited looks on their faces), it would be good to see them *enjoying* the indulgence - interacting with each other, putting on the life jackets, or just starting/coming to a stop (i.e. with some bow waves or wake to show movement) would all have dramatically improved the image.', '2006-06-14 08:41:52.000000', NULL, 1),
(2515672, 345715, 58060, '<td valign="top">Strange cubists clouds</td>', 'Strange cubists clouds', '2006-06-14 08:45:13.000000', NULL, 1),
(2515674, 345828, 58060, '<td valign="top">Alligator ?</td>', 'Alligator ?', '2006-06-14 08:46:11.000000', NULL, 1),
(2515675, 345114, 50715, '<td valign="top">Great image! I like the composition and the unusual aspect ratio - the panaromic-type proportions. Having the model facing away from the camera towards the candles reinforces the feeling of relaxation and indulgence. Something about the lighting doesn''t look quite right (the clash between the low warm red light from the left of frame and the stronger white light from above?), although I imagine this would be difficult to light really well.</td>', 'Great image! I like the composition and the unusual aspect ratio - the panaromic-type proportions. Having the model facing away from the camera towards the candles reinforces the feeling of relaxation and indulgence. Something about the lighting doesn''t look quite right (the clash between the low warm red light from the left of frame and the stronger white light from above?), although I imagine this would be difficult to light really well.', '2006-06-14 08:46:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2515679, 347510, 50715, '<td valign="top">This image made me smile, the model''s pleasure is infectious. Well composed, nice and sharp, background is non-distracting - I expect some might not like the really dark background, but it works for me.</td>', 'This image made me smile, the model''s pleasure is infectious. Well composed, nice and sharp, background is non-distracting - I expect some might not like the really dark background, but it works for me.', '2006-06-14 08:47:53.000000', NULL, 1),
(2515682, 346911, 50715, '<td valign="top">Interesting still life. The choice of colours and lighting directions work well for me, particularly the control of the lighting on the background (i.e. not lighting the entire background).</td>', 'Interesting still life. The choice of colours and lighting directions work well for me, particularly the control of the lighting on the background (i.e. not lighting the entire background).', '2006-06-14 08:49:22.000000', NULL, 1),
(2515697, 346807, 50715, '<td valign="top">Sorry, but this one doesn''t work much for me, it seems to only just escape being a literal representation of someone else''s artwork. You''ve thought about composition and combining the picture element with the CD - but as a photo, it looks too flat to carry much impact.</td>', 'Sorry, but this one doesn''t work much for me, it seems to only just escape being a literal representation of someone else''s artwork. You''ve thought about composition and combining the picture element with the CD - but as a photo, it looks too flat to carry much impact.', '2006-06-14 08:53:30.000000', NULL, 1),
(2515704, 347486, 18207, '<td valign="top">Interesting background, I''m still not sure about it. For me, for now, it somehow shows how the fly senses the scent of the icecream. In this way, it''s great!</td>', 'Interesting background, I''m still not sure about it. For me, for now, it somehow shows how the fly senses the scent of the icecream. In this way, it''s great!', '2006-06-14 08:54:49.000000', NULL, 1),
(2515716, 347380, 50715, '<td valign="top">This looks a bit too busy for my liking; it ends up just being a jumble of boat shapes without carrying a lot of impact - either in terms of sheer size or luxuriousness. I think this is a case where "less is more" - if you could isolate one of the yachts, particularly a large one (with something else to give a reference point for size) then it would work better. Other yachts in the background would be ok, but these are too mixed up together.</td>', 'This looks a bit too busy for my liking; it ends up just being a jumble of boat shapes without carrying a lot of impact - either in terms of sheer size or luxuriousness. I think this is a case where "less is more" - if you could isolate one of the yachts, particularly a large one (with something else to give a reference point for size) then it would work better. Other yachts in the background would be ok, but these are too mixed up together.', '2006-06-14 08:56:59.000000', NULL, 1),
(2515723, 345216, 50715, '<td valign="top">Nice detail and lighting, good variation in the colours adds interest, and stacking them makes a nice change from simply putting them on a plate. The objects in the background intrude a little too much though - maybe having them a bit further off or more to one side might help?</td>', 'Nice detail and lighting, good variation in the colours adds interest, and stacking them makes a nice change from simply putting them on a plate. The objects in the background intrude a little too much though - maybe having them a bit further off or more to one side might help?', '2006-06-14 08:58:26.000000', NULL, 1),
(2515732, 346537, 50715, '<td valign="top">Nice simple image, fits the theme very well. Having the matting cover the entire background of the frame helps make the image - if there were other background elements then it would be a bit distracting. Looks like a dog''s eye view, which is a nice touch too. :)</td>', 'Nice simple image, fits the theme very well. Having the matting cover the entire background of the frame helps make the image - if there were other background elements then it would be a bit distracting. Looks like a dog''s eye view, which is a nice touch too. :)', '2006-06-14 09:00:17.000000', NULL, 1),
(2515747, 345943, 50715, '<td valign="top">Good choice of subject and a nice action shot with the subject very sharp - but the background is also so sharp, that it is very distracting. Using a wider aperture would help. One option would be to move back and use a longer lens to reduce your depth of field - another would be to move in with a strong wide-angle lens to help isolate the subject from the background.</td>', 'Good choice of subject and a nice action shot with the subject very sharp - but the background is also so sharp, that it is very distracting. Using a wider aperture would help. One option would be to move back and use a longer lens to reduce your depth of field - another would be to move in with a strong wide-angle lens to help isolate the subject from the background.', '2006-06-14 09:03:17.000000', NULL, 1),
(2515759, 347048, 18207, '<td valign="top">I can''t see indulgence on this shot of not the best quality.</td>', 'I can''t see indulgence on this shot of not the best quality.', '2006-06-14 09:05:14.000000', NULL, 1),
(2515763, 346738, 50715, '<td valign="top">This image is playing tricks on me - the flower is (in parts) very sharp, the diamonds reasonably sharp, but the pearls are way too soft - maybe the depth of field is TOO narrow? The composition is also a little bit too square and orthogonal for my liking - introducing some angles to add a little "movement" or dynamism would help a lot.</td>', 'This image is playing tricks on me - the flower is (in parts) very sharp, the diamonds reasonably sharp, but the pearls are way too soft - maybe the depth of field is TOO narrow? The composition is also a little bit too square and orthogonal for my liking - introducing some angles to add a little "movement" or dynamism would help a lot.', '2006-06-14 09:05:47.000000', NULL, 1),
(2515773, 346443, 18207, '<td valign="top">This shot has a great potential, I really miss the details and the colors.</td>', 'This shot has a great potential, I really miss the details and the colors.', '2006-06-14 09:07:20.000000', NULL, 1),
(2515779, 346562, 50715, '<td valign="top">Good composition and interesting choice of subject :) The only criticism I can think of is that the diamonds are a bit soft and dull (a bit more light could make them dazzle a bit more), and the clothing elastic mark (or is it a scratch?) on the model''s right cheek is very distracting. Otherwise, nicely done.</td>', 'Good composition and interesting choice of subject :) The only criticism I can think of is that the diamonds are a bit soft and dull (a bit more light could make them dazzle a bit more), and the clothing elastic mark (or is it a scratch?) on the model''s right cheek is very distracting. Otherwise, nicely done.', '2006-06-14 09:08:37.000000', NULL, 1),
(2515806, 347510, 15711, '<td valign="top">This made me smile.</td>', 'This made me smile.', '2006-06-14 09:17:06.000000', NULL, 1),
(2515808, 346098, 15711, '<td valign="top">Great title. The shot seems a tad underexposed, but a layers or curves adjustement might help with the overall richness of tone.</td>', 'Great title. The shot seems a tad underexposed, but a layers or curves adjustement might help with the overall richness of tone.', '2006-06-14 09:18:09.000000', NULL, 1),
