(2521114, 346098, 57658, '<td valign="top">Nice idea but needs better execution. All the fine detail of the gold is lost - I''m guessing you had trouble meeting the 150K size requirements.Perhaps focussing on the centerpiece or a pillar...</td>', 'Nice idea but needs better execution. All the fine detail of the gold is lost - I''m guessing you had trouble meeting the 150K size requirements.Perhaps focussing on the centerpiece or a pillar...', '2006-06-15 20:08:48.000000', NULL, 1),
(2521121, 346807, 57658, '<td valign="top">Simple (perhaps overly so because this is more a photo of a photo ) - good rainbow colors on the CD - a bit subtle though - almost missed it. Its a little annoying that some objects are cropped off on all but one side - the horn on the left (with something above it, the battle axe on top and the S and R on the bottom) - 4</td>', 'Simple (perhaps overly so because this is more a photo of a photo ) - good rainbow colors on the CD - a bit subtle though - almost missed it. Its a little annoying that some objects are cropped off on all but one side - the horn on the left (with something above it, the battle axe on top and the S and R on the bottom) - 4', '2006-06-15 20:11:56.000000', NULL, 1),
(2521125, 347355, 57658, '<td valign="top">very nicely executed - could use a cleverer title :D .. May I suggest "The greens" . 8</td>', 'very nicely executed - could use a cleverer title :D .. May I suggest "The greens" . 8', '2006-06-15 20:13:09.000000', NULL, 1),
(2521127, 344517, 57658, '<td valign="top">I like the artsy approach but the composition doesn''t hold me - perhaps if the eye was a little lower - the white needs more balance from the black hair. 4</td>', 'I like the artsy approach but the composition doesn''t hold me - perhaps if the eye was a little lower - the white needs more balance from the black hair. 4', '2006-06-15 20:14:35.000000', NULL, 1),
(2521132, 346961, 57658, '<td valign="top">Wonderful shades of gray but there is too much going on here - perhaps more of a height crop or just one person walking next to the car and admiring it ? 5</td>', 'Wonderful shades of gray but there is too much going on here - perhaps more of a height crop or just one person walking next to the car and admiring it ? 5', '2006-06-15 20:15:51.000000', NULL, 1);
