(2523608, 346783, 42957, '<td valign="top">she looks pissed at something. nice DOF, though--lovely blurred background.  i think it''s more of an indulgence to be able to lie on the beach and work with a laptop! :)</td>', 'she looks pissed at something. nice DOF, though--lovely blurred background.  i think it''s more of an indulgence to be able to lie on the beach and work with a laptop! :)', '2006-06-17 02:00:50.000000', NULL, 1),
(2523612, 346835, 42957, '<td valign="top">Great capture! I love the expressions on the girls'' faces and how they''re really, literally, <i>digging in</i>.  This looks like the steps along Ala Moana Beach--and aloha print! Oh, this hits very close to home for me.  Lovely watermelon and beach memories. :)</td>', 'Great capture! I love the expressions on the girls'' faces and how they''re really, literally, digging in.  This looks like the steps along Ala Moana Beach--and aloha print! Oh, this hits very close to home for me.  Lovely watermelon and beach memories. :)', '2006-06-17 02:04:29.000000', NULL, 1),
(2523615, 346247, 42957, '<td valign="top">This deserves a ribbon.  This is so sweet!  I love how the girl''s jacket looks soft like the cotton candy. Lovely lighting, although it''s a bit harsh on the left side of the cotton candy and on her left shoulder.  Anyway, you captured childhood wonderfully!</td>', 'This deserves a ribbon.  This is so sweet!  I love how the girl''s jacket looks soft like the cotton candy. Lovely lighting, although it''s a bit harsh on the left side of the cotton candy and on her left shoulder.  Anyway, you captured childhood wonderfully!', '2006-06-17 02:06:59.000000', NULL, 1),
(2523616, 347432, 42957, '<td valign="top">Whoa. I honestly can''t understand putting all of that on your face.  Anyway, it''s a fun shot--great DOF, textures, and colors!</td>', 'Whoa. I honestly can''t understand putting all of that on your face.  Anyway, it''s a fun shot--great DOF, textures, and colors!', '2006-06-17 02:08:03.000000', NULL, 1),
(2523618, 345377, 42957, '<td valign="top">dude this is psychedelic--i respect! <br/> <br/>I love looking at this image...maybe just a little bit more color would add some more oomph, but I realy love it.  added to favorites.</td>', 'dude this is psychedelic--i respect!  I love looking at this image...maybe just a little bit more color would add some more oomph, but I realy love it.  added to favorites.', '2006-06-17 02:10:03.000000', NULL, 1),
(2523630, 347486, 25678, '<td valign="top">Awesome shot.  You''re in my top picks.  Good luck!</td>', 'Awesome shot.  You''re in my top picks.  Good luck!', '2006-06-17 02:20:52.000000', NULL, 1),
(2523661, 346804, 51796, '<td valign="top">A reflector would have really helped - great idea anyway.</td>', 'A reflector would have really helped - great idea anyway.', '2006-06-17 02:47:17.000000', NULL, 1),
(2523769, 345377, 46832, '<td valign="top">Someone is overindulging with the IR.</td>', 'Someone is overindulging with the IR.', '2006-06-17 05:58:21.000000', NULL, 1),
(2523770, 345826, 46832, '<td valign="top">Interesting - but there is no oil on the end of the dipstick.</td>', 'Interesting - but there is no oil on the end of the dipstick.', '2006-06-17 05:59:20.000000', NULL, 1),
(2523771, 347503, 46832, '<td valign="top">I could have gone the rest of my life without seeing that.</td>', 'I could have gone the rest of my life without seeing that.', '2006-06-17 06:00:13.000000', NULL, 1),
(2523829, 347551, 31133, '<td valign="top">Great colors. This would make a perfect stock photo.</td>', 'Great colors. This would make a perfect stock photo.', '2006-06-17 08:05:49.000000', NULL, 1),
(2523834, 347486, 31133, '<td valign="top">I really love the composition and well, the whole idea. The thing I can think of that might make it even more appealing is if the candy were a solid color, since the peppermint stripes sort of lead the eye away from the fly, rather than to him.</td>', 'I really love the composition and well, the whole idea. The thing I can think of that might make it even more appealing is if the candy were a solid color, since the peppermint stripes sort of lead the eye away from the fly, rather than to him.', '2006-06-17 08:07:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2523836, 347522, 31133, '<td valign="top">I''m the last person who should be saying this, since I''m guilty of it too, but I think there''s a tad too much Neat Image, at least on the person''s foot / ankle area. The colors are very good.</td>', 'I''m the last person who should be saying this, since I''m guilty of it too, but I think there''s a tad too much Neat Image, at least on the person''s foot / ankle area. The colors are very good.', '2006-06-17 08:09:55.000000', NULL, 1),
(2523839, 347589, 31133, '<td valign="top">There are only two things that can criticize about this image: (1) I wish the teeth weren''t so white (looks a little fake) and (2) The camera had been a bit to the right or left to avoid the lamp shade growing out of the woman''s head.  Otherwise, I think this is a truly gorgeous shot! I would love to be in this scene... food, comfort, beauty, wine, ... you''ve got it all. Is this you, Shail? Nice job!</td>', 'There are only two things that can criticize about this image: (1) I wish the teeth weren''t so white (looks a little fake) and (2) The camera had been a bit to the right or left to avoid the lamp shade growing out of the woman''s head.  Otherwise, I think this is a truly gorgeous shot! I would love to be in this scene... food, comfort, beauty, wine, ... you''ve got it all. Is this you, Shail? Nice job!', '2006-06-17 08:18:04.000000', NULL, 1),
(2523840, 345247, 31133, '<td valign="top">You have definitely met the topic of indulgence :-) but I think there''s a little too much. To use the photo-critic style of some things I''ve read, my eye has nowhere to rest.</td>', 'You have definitely met the topic of indulgence :-) but I think there''s a little too much. To use the photo-critic style of some things I''ve read, my eye has nowhere to rest.', '2006-06-17 08:20:04.000000', NULL, 1),
(2523843, 347498, 31133, '<td valign="top">The title is great! I think you might get other comments like mine, so I apologize if you''re tired of hearing it, but I wish the focus was better. If it were, I think you would have a much higher scoring entry. The color of that bug is unusual... very interesting!</td>', 'The title is great! I think you might get other comments like mine, so I apologize if you''re tired of hearing it, but I wish the focus was better. If it were, I think you would have a much higher scoring entry. The color of that bug is unusual... very interesting!', '2006-06-17 08:22:41.000000', NULL, 1),
(2523844, 346849, 31133, '<td valign="top">Heh, heh I really like this on so many levels. I love how my brain is led from the yummmmm, yummm ice cream to the "oh yeah, oh no" realization of the after effects ;-) You''ve told a story with your depth of focus, that''s for sure. Wonderful colors as well.</td>', 'Heh, heh I really like this on so many levels. I love how my brain is led from the yummmmm, yummm ice cream to the "oh yeah, oh no" realization of the after effects ;-) You''ve told a story with your depth of focus, that''s for sure. Wonderful colors as well.', '2006-06-17 08:25:38.000000', NULL, 1),
(2523845, 345828, 31133, '<td valign="top">ha haha someone was overindulging while holding a camera :-)</td>', 'ha haha someone was overindulging while holding a camera :-)', '2006-06-17 08:26:36.000000', NULL, 1),
(2523846, 345944, 31133, '<td valign="top">eeewwww, you own her? Weird title, but pretty nice image.</td>', 'eeewwww, you own her? Weird title, but pretty nice image.', '2006-06-17 08:27:57.000000', NULL, 1),
(2523848, 346770, 31133, '<td valign="top">Good focus and colors. I''d like to see some more empty space (water) to the left. It was probably impossible to do, but if the angle was such that you could crop out the land part, I think it would''ve been very, very good. But I know that when an image presents itself, you''ve just gotta shoot it! I like the expressions on the boys'' faces.</td>', 'Good focus and colors. I''d like to see some more empty space (water) to the left. It was probably impossible to do, but if the angle was such that you could crop out the land part, I think it would''ve been very, very good. But I know that when an image presents itself, you''ve just gotta shoot it! I like the expressions on the boys'' faces.', '2006-06-17 08:31:45.000000', NULL, 1),
(2523849, 346237, 31133, '<td valign="top">Now this looks English! Nice and careful composition. I''m hungry now.</td>', 'Now this looks English! Nice and careful composition. I''m hungry now.', '2006-06-17 08:32:40.000000', NULL, 1),
(2523850, 346630, 31133, '<td valign="top">Good job! The dof really draws me in to those two lovebugs. Wish the top of the leaf were completely in the frame.</td>', 'Good job! The dof really draws me in to those two lovebugs. Wish the top of the leaf were completely in the frame.', '2006-06-17 08:34:34.000000', NULL, 1),
(2523851, 347366, 31133, '<td valign="top">GREAT angle! The blue is perfect as can be and you (unlike me) managed to get it with zero blown highlights. I love the way you''ve cropped at the top to leave just enough, but not too much, blue sky.</td>', 'GREAT angle! The blue is perfect as can be and you (unlike me) managed to get it with zero blown highlights. I love the way you''ve cropped at the top to leave just enough, but not too much, blue sky.', '2006-06-17 08:36:23.000000', NULL, 1),
(2523852, 347510, 31133, '<td valign="top">What a winning smile!!</td>', 'What a winning smile!!', '2006-06-17 08:37:33.000000', NULL, 1),
(2523853, 347380, 31133, '<td valign="top">Meets the challenge, but there''s a slight blue overtone that makes the lighting seem off. Also the blown highlight on the boat to the right is distracting. Looks like a gorgeous day, though!</td>', 'Meets the challenge, but there''s a slight blue overtone that makes the lighting seem off. Also the blown highlight on the boat to the right is distracting. Looks like a gorgeous day, though!', '2006-06-17 08:38:55.000000', NULL, 1),
(2523855, 345408, 31133, '<td valign="top">Love it! (wish the shiny reflections in the floor and behind the dog''s ear weren''t there, though).</td>', 'Love it! (wish the shiny reflections in the floor and behind the dog''s ear weren''t there, though).', '2006-06-17 08:41:31.000000', NULL, 1),
(2523856, 345377, 31133, '<td valign="top">WOW, I have to try this someday. Of course, it will never in a million years be as beautiful as this, but one can hope.</td>', 'WOW, I have to try this someday. Of course, it will never in a million years be as beautiful as this, but one can hope.', '2006-06-17 08:42:33.000000', NULL, 1),
(2523860, 346911, 34192, '<td valign="top">interesting.  Wish there was more light and less shadow.  I like the yellow but not the maroon.  In focus.</td>', 'interesting.  Wish there was more light and less shadow.  I like the yellow but not the maroon.  In focus.', '2006-06-17 08:44:20.000000', NULL, 1),
(2523861, 346539, 34192, '<td valign="top">lighting a little harsh - loses what could be the richness of the colors.  Focus and Dof good.</td>', 'lighting a little harsh - loses what could be the richness of the colors.  Focus and Dof good.', '2006-06-17 08:45:19.000000', NULL, 1),
(2523864, 346807, 34192, '<td valign="top">while the image is interesting I think it is someone else''s artwork that makes it that way.</td>', 'while the image is interesting I think it is someone else''s artwork that makes it that way.', '2006-06-17 08:46:15.000000', NULL, 1),
(2523865, 346961, 34192, '<td valign="top">really like this image.  whites are whites and blacks are blacks but think the mids could be just a hair lighter.  Love the POV.  Dof and focus are well done.</td>', 'really like this image.  whites are whites and blacks are blacks but think the mids could be just a hair lighter.  Love the POV.  Dof and focus are well done.', '2006-06-17 08:47:27.000000', NULL, 1),
(2523872, 347577, 34192, '<td valign="top">focus is good but the white balance is off - looks like you used indoor tungsten lighting.  Comp works.</td>', 'focus is good but the white balance is off - looks like you used indoor tungsten lighting.  Comp works.', '2006-06-17 08:57:09.000000', NULL, 1),
(2523876, 347486, 34192, '<td valign="top">something bizarre about this but not sure if its the title or the candy.  Bizarre in a good way, yes.  comp well done, DOF and POV excellent.  Like your use of background space.  well done.</td>', 'something bizarre about this but not sure if its the title or the candy.  Bizarre in a good way, yes.  comp well done, DOF and POV excellent.  Like your use of background space.  well done.', '2006-06-17 09:00:29.000000', NULL, 1),
(2523877, 347503, 34192, '<td valign="top">men are such...well, men.  Flash is readily apparent - the image could use a touch of contrast.  Focus good.</td>', 'men are such...well, men.  Flash is readily apparent - the image could use a touch of contrast.  Focus good.', '2006-06-17 09:01:31.000000', NULL, 1),
(2523878, 346756, 34192, '<td valign="top">focus and colors good.  DOF and POV good.</td>', 'focus and colors good.  DOF and POV good.', '2006-06-17 09:03:39.000000', NULL, 1),
(2523880, 347600, 34192, '<td valign="top">focus and DOF good.  Image a little static but you''ve capture the chrome well.</td>', 'focus and DOF good.  Image a little static but you''ve capture the chrome well.', '2006-06-17 09:04:50.000000', NULL, 1),
(2523882, 346172, 34192, '<td valign="top">POV, focus, DOF good.  this offers a little more to the senses than some of the other car shots.</td>', 'POV, focus, DOF good.  this offers a little more to the senses than some of the other car shots.', '2006-06-17 09:06:00.000000', NULL, 1),
(2523883, 346783, 34192, '<td valign="top">focus, DOF and POV good.  interesting take on the challenge.</td>', 'focus, DOF and POV good.  interesting take on the challenge.', '2006-06-17 09:06:33.000000', NULL, 1),
(2523885, 347536, 34192, '<td valign="top">focus, dof, pov all well done.  Colors good.</td>', 'focus, dof, pov all well done.  Colors good.', '2006-06-17 09:07:19.000000', NULL, 1),
(2523886, 347454, 34192, '<td valign="top">funny.  a little bit blown.  focus a little soft, due to slow shutter?</td>', 'funny.  a little bit blown.  focus a little soft, due to slow shutter?', '2006-06-17 09:08:11.000000', NULL, 1),
(2523887, 347509, 34192, '<td valign="top">composition very well done.  Focus and DOF excellent for subject.</td>', 'composition very well done.  Focus and DOF excellent for subject.', '2006-06-17 09:09:10.000000', NULL, 1),
(2523888, 347335, 34192, '<td valign="top">i really like the use of the sign - it adds a lot to the image.  I think your crop in that respect is excellent.  timing and focus and DOF are well done. bump 10</td>', 'i really like the use of the sign - it adds a lot to the image.  I think your crop in that respect is excellent.  timing and focus and DOF are well done. bump 10', '2006-06-17 09:10:04.000000', NULL, 1),
